import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BlogPostClient from './blog-post'
import type { Post, Comment } from '@/types'

export const dynamicParams = true
export const revalidate = 300

interface PageProps {
  params: Promise<{ id: string }>
}

export async function generateStaticParams() {
  const posts: Post[] = await fetch('https://jsonplaceholder.typicode.com/posts').then(
    (res) => res.json()
  )

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

export async function generateMetadata({ params }: PageProps): Promise<Metadata> {
  const { id } = await params
  try {
    const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
      next: { revalidate: 300 },
    })
    if (!res.ok) {
      return {
        title: 'Post Not Found - My Blog',
      }
    }
    const post: Post = await res.json()
    if (!post || !post.title) {
      return {
        title: 'Post Not Found - My Blog',
      }
    }
    const description = post.body ? post.body.substring(0, 160) : ''
    return {
      title: `${post.title} - My Blog`,
      description,
      openGraph: {
        title: post.title,
        description,
      },
    }
  } catch {
    return {
      title: 'Post Not Found - My Blog',
    }
  }
}

async function getPostData(id: string): Promise<{ post: Post; comments: Comment[] }> {
  let postRes: Response
  let commentsRes: Response
  try {
    const responses = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ])
    postRes = responses[0]
    commentsRes = responses[1]
  } catch {
    notFound()
  }

  if (!postRes.ok) {
    notFound()
  }

  const post: Post = await postRes.json().catch(() => null)
  if (!post || !post.id || !post.title) {
    notFound()
  }

  const comments: Comment[] = commentsRes.ok
    ? await commentsRes.json().catch(() => [])
    : []

  return { post, comments }
}

export default async function BlogPostPage({ params }: PageProps) {
  const { id } = await params
  const { post, comments } = await getPostData(id)

  return <BlogPostClient post={post} comments={comments} />
}

